use std::{fs,path::PathBuf,sync::Mutex};
use serde::{Serialize,Deserialize};
use tauri::{AppHandle,Manager,State};
use crate::startup_core::{startup_command,initial_startup};
#[derive(Default)]pub struct Startup(pub Mutex<()>);
#[derive(Serialize)]#[serde(rename_all="camelCase")]pub struct Status{enabled:bool,supported:bool,automatic_launch:bool}
#[derive(Serialize,Deserialize)]struct Settings{enabled:bool}
fn config(app:&AppHandle)->Result<PathBuf,String>{Ok(app.path().app_config_dir().map_err(|_|"No se encontró la configuración.")?.join("startup-v1.json"))}
fn preference(app:&AppHandle)->Result<Option<bool>,String>{let path=config(app)?;if !path.exists(){return Ok(None)}let bytes=fs::read(path).map_err(|_|"No se pudo leer el inicio automático.")?;if bytes.len()>1024{return Err("La configuración de inicio está dañada.".into())}Ok(Some(serde_json::from_slice::<Settings>(&bytes).map_err(|_|"La configuración de inicio está dañada.")?.enabled))}
fn save(app:&AppHandle,enabled:bool)->Result<(),String>{let path=config(app)?;fs::create_dir_all(path.parent().ok_or("Ruta inválida.")?).map_err(|e|e.to_string())?;let tmp=path.with_extension("tmp");fs::write(&tmp,serde_json::to_vec(&Settings{enabled}).map_err(|e|e.to_string())?).map_err(|e|e.to_string())?;fs::rename(tmp,path).map_err(|e|e.to_string())}
#[cfg(windows)]fn register(enabled:bool)->Result<(),String>{use winreg::{RegKey,enums::HKEY_CURRENT_USER};let (key,_)=RegKey::predef(HKEY_CURRENT_USER).create_subkey(r"Software\Microsoft\Windows\CurrentVersion\Run").map_err(|_|"Windows no permitió configurar el inicio de Bimu.")?;if enabled{let command=startup_command(&std::env::current_exe().map_err(|e|e.to_string())?)?;key.set_value("Bimu",&command).map_err(|_|"No se pudo activar el inicio con Windows.".into())}else{match key.delete_value("Bimu"){Ok(())=>Ok(()),Err(e) if e.kind()==std::io::ErrorKind::NotFound=>Ok(()),Err(_)=>Err("No se pudo desactivar el inicio con Windows.".into())}}}
#[cfg(not(windows))]fn register(_enabled:bool)->Result<(),String>{Err("El inicio automático requiere Windows.".into())}
fn status(enabled:bool)->Status{Status{enabled,supported:cfg!(windows)&&!cfg!(debug_assertions),automatic_launch:std::env::args().any(|arg|arg=="--autostart")}}
#[tauri::command]pub fn startup_sync(listen_preferred:bool,app:AppHandle,state:State<'_,Startup>)->Result<Status,String>{let _guard=state.inner().0.lock().map_err(|_|"Inicio ocupado.")?;if !cfg!(windows)||cfg!(debug_assertions){return Ok(status(false))}let old=preference(&app)?;let enabled=initial_startup(old,listen_preferred);if let Some(value)=enabled{register(value)?;if old.is_none(){if let Err(e)=save(&app,value){let _=register(false);return Err(e)}}}Ok(status(enabled.unwrap_or(false)))}
#[tauri::command]pub fn startup_set(enabled:bool,app:AppHandle,state:State<'_,Startup>)->Result<Status,String>{let _guard=state.inner().0.lock().map_err(|_|"Inicio ocupado.")?;if !cfg!(windows)||cfg!(debug_assertions){return Err("El inicio con Windows está disponible en la app instalada.".into())}let old=preference(&app)?.unwrap_or(false);register(enabled)?;if let Err(e)=save(&app,enabled){let _=register(old);return Err(e)}Ok(status(enabled))}
